"use strict";

const ADD_WASM_BYTES = [
  0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
  0x01, 0x07, 0x01, 0x60, 0x02, 0x7f, 0x7f, 0x01,
  0x7f, 0x03, 0x02, 0x01, 0x00, 0x07, 0x07, 0x01,
  0x03, 0x61, 0x64, 0x64, 0x00, 0x00, 0x0a, 0x09,
  0x01, 0x07, 0x00, 0x20, 0x00, 0x20, 0x01, 0x6a,
  0x0b,
];

module.exports = async function wasmBufferProbe() {
  const bytes = Buffer.from(ADD_WASM_BYTES);
  const module = await WebAssembly.compile(bytes);
  const first = await WebAssembly.instantiate(module);
  const second = await WebAssembly.instantiate(module);
  const value = first.exports.add(8, 9);
  const checksum = bytes[0] + bytes[1] + bytes[2] + bytes[3];
  return {
    value,
    summary: `wasm:buffer/${value}/${checksum + second.exports.add(0, 0)}`,
  };
};
